mapper.select:
SELECT f.id, f.biz_type, f.biz_id, f.biz_no, f.movement_id, f.material_id, m.code AS material_code, m.name AS material_name, f.warehouse_id, w.name AS warehouse_name, f.biz_date, f.qty, f.unit_cost, f.amount, f.balance_qty, f.balance_cost, f.period FROM cost_flow f LEFT JOIN base_material m ON m.id = f.material_id LEFT JOIN base_warehouse w ON w.id = f.warehouse_id WHERE f.deleted = 0
AND f.period = #{q.period}
AND f.material_id = #{q.materialId}
AND f.biz_type = #{q.bizType}
AND (f.biz_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY f.id DESC
